export function resolveSpawnExecutable(argv0, options = {}) {
  const platform = options.platform ?? process.platform;
  if (platform === "win32") return { ok: false, reason: "unsupported-platform", platform };
  const cwd = options.cwd ?? process.cwd(), env = options.env ?? process.env;
  const stat = options.stat ?? statSync, access = options.access ?? accessSync;
  const defaultPath = options.posixDefaultPath ?? "/usr/bin:/bin", direct = argv0.includes("/");
  const searchPath = Object.hasOwn(env, "PATH") ? env.PATH : null;
  const source = searchPath === null ? `the POSIX default search path ${defaultPath}` : "POSIX PATH";
  // An empty PATH entry means the current directory, which is why `entry || "."` is not a no-op.
  const candidates = direct ? [posix.isAbsolute(argv0) ? argv0 : posix.resolve(cwd, argv0)]
    : (searchPath ?? defaultPath).split(":").map((entry) => posix.join(posix.resolve(cwd, entry || "."), argv0));
  for (const candidate of candidates) {
    try {
      if (!stat(candidate).isFile()) continue;
      access(candidate, constants.X_OK);
      return { ok: true, path: candidate, source: direct ? "its direct path" : source };
    } catch {}
  }
  return { ok: false, reason: "not-executable", source: direct ? "its direct path" : source };
}

function failure(message) {
  return new Error(message);
}

function execute(run, args) {
  // No `encoding`: stdout stays a Buffer. Decoding to utf8 replaces every distinct
  // invalid byte sequence with the same U+FFFD, so two unequal targets could compare
  // equal here while `git push` used the original raw bytes. A local-path remote on
  // Unix may legitimately hold non-UTF-8 bytes, so this is reachable, not theoretical.
  return run("git", args, {
    shell: false,
    env: { ...process.env, LC_ALL: "C" },
    stdio: ["ignore", "pipe", "pipe"],
  });
}

function capture(run, repository) {
  let result;
  try {
    result = execute(run, ["-C", repository, "remote", "get-url", "--push", "origin"]);
  } catch {
    return null;
  }
  if (!result || result.error || result.signal !== null && result.signal !== undefined
    || result.status !== 0 || result.stdout === null || result.stdout === undefined) return null;
  // A test double may still hand back a string; normalise to bytes either way.
  const raw = Buffer.isBuffer(result.stdout) ? result.stdout : Buffer.from(String(result.stdout), "utf8");
  // Exactly one LF, because git contributes exactly one record terminator. Stripping every
  // trailing LF would make a target that itself ends in LF indistinguishable from one that
  // does not: operator bytes `path\n` are emitted as `path\n\n` and sandbox bytes `path` as
  // `path\n`, and a greedy strip reduces both to `path` and accepts two unequal targets.
  // Absent terminator means this is not the output shape being parsed, so fail closed.
  if (raw.length === 0 || raw[raw.length - 1] !== 0x0a) return null;
  const target = raw.subarray(0, raw.length - 1);
  return target.length > 0 ? Buffer.from(target) : null;
}

function argvSafe(target) {
  return Buffer.from(target.toString("utf8"), "utf8").equals(target);
}

function configure(run, repository, target) {
  try {
    return execute(run, ["-C", repository, "config", "--replace-all", "remote.origin.pushurl", target])?.status === 0;
  } catch {
    return false;
  }
}

export function enforceEffectivePushTarget(positionals, { spawnSync: run = spawnSync } = {}) {
  if (!Array.isArray(positionals) || positionals.length !== 3) throw failure(ARITY_ERROR);
  if (positionals.some((value) => typeof value !== "string" || value.length === 0)) throw failure(EMPTY_ERROR);
  const [operation, operatorRepository, sandboxRepository] = positionals;
  if (operation !== "bootstrap" && operation !== "check") throw failure(OPERATION_ERROR);

  let operatorTarget = capture(run, operatorRepository);
  if (operatorTarget === null) {
    throw failure(`factory sandbox: operator effective push target unavailable; sandbox retained at ${sandboxRepository}`);
  }
  if (operation === "bootstrap") {
    if (!argvSafe(operatorTarget)) {
      throw failure(`factory sandbox: operator effective push target is not representable for configuration; sandbox retained at ${sandboxRepository}`);
    }
    if (!configure(run, sandboxRepository, operatorTarget.toString("utf8"))) {
      throw failure(`factory sandbox: sandbox effective push target unavailable at ${sandboxRepository}`);
    }
    operatorTarget = capture(run, operatorRepository);
    if (operatorTarget === null) {
      throw failure(`factory sandbox: operator effective push target unavailable; sandbox retained at ${sandboxRepository}`);
    }
  }
  const sandboxTarget = capture(run, sandboxRepository);
  if (sandboxTarget === null) {
    throw failure(`factory sandbox: sandbox effective push target unavailable at ${sandboxRepository}`);
  }
  if (!sandboxTarget.equals(operatorTarget)) {
    throw failure(`factory sandbox: sandbox effective push target does not match operator target; sandbox retained at ${sandboxRepository}`);
  }
}

export function git(cwd, args, { runner = spawnSync } = {}) {
  const result = runner("git", args, { cwd, encoding: "utf8", shell: false, env: { ...process.env, LC_ALL: "C" } });
  const status = Number.isInteger(result?.status) ? result.status : null;
  return {
    ok: status === 0,
    status,
    stdout: String(result?.stdout ?? ""),
    stderr: String(result?.stderr ?? ""),
    argv: ["git", ...args],
  };
}

export function observeWorktree(worktree, baseRef, options = {}) {
  const ref = options.ref ?? "HEAD";
  const commands = [];
  const record = (result) => {
    commands.push({ cmd: result.argv.join(" "), exit: result.status, summary: summarize(result) });
    return result;
  };

  const head = record(git(worktree, ["rev-parse", ref], options));
  const names = record(git(worktree, ["--literal-pathspecs", "diff", "--name-only", "-z", `${baseRef}...${ref}`], options));
  const stat = record(git(worktree, ["diff", "--stat", `${baseRef}...${ref}`], options));

  const observed = head.ok && names.ok && stat.ok;
  return {
    commit: head.ok ? head.stdout.trim() : null,
    // NUL-separated and untrimmed: ownership is decided on these paths, so a name with a
    // trailing space must stay a distinct path rather than collapsing onto another.
    files_changed: names.ok ? names.stdout.split("\0").filter((path) => path !== "") : [],
    diff_stat: stat.ok ? stat.stdout.trim() : null,
    diff_observed: observed,
    commands,
  };
}

const record = (result) => {
  commands.push({ cmd: result.argv.join(" "), exit: result.status, summary: summarize(result) });
  return result;
};

export function observeCleanliness(worktree, options = {}) {
  const probe = git(worktree, ["status", "--porcelain", "--untracked-files=normal"], options);
  if (!probe.ok) return { clean: false, reason: "worktree state could not be observed", entries: [] };
  const entries = probe.stdout.split("\n").map((line) => line.trim()).filter(Boolean);
  return { clean: entries.length === 0, reason: entries.length === 0 ? null : "worktree has uncommitted changes", entries };
}

export function runBootstrap(worktree, command, timeoutMs = DEFAULT_BOOTSTRAP_TIMEOUT_MS, { runner = spawnSync } = {}) {
  try {
    const result = runner(command, [], {
      cwd: worktree, shell: true, env: process.env, timeout: timeoutMs, stdio: ["inherit", process.stderr, process.stderr],
    });
    return Number.isSafeInteger(result?.status) && result.status >= 0 ? result.status : null;
  } catch { return null; }
}

export function observeTrackedCleanliness(worktree, options = {}) {
  try {
    const top = git(worktree, ["rev-parse", "--show-toplevel"], options);
    const probes = [
      git(worktree, ["--literal-pathspecs", "diff", "--name-only", "-z"], options),
      git(worktree, ["--literal-pathspecs", "diff", "--cached", "--name-only", "-z"], options),
    ];
    if (!top.ok || realpathSync(resolve(worktree, top.stdout.trim())) !== realpathSync(worktree)
      || probes.some((probe) => !probe.ok)) return { observed: false, entries: [] };
    return { observed: true, entries: [...new Set(probes.flatMap((probe) => probe.stdout.split("\0").filter(Boolean)))].sort() };
  } catch { return { observed: false, entries: [] }; }
}

export function observeAncestry(worktree, ancestor, descendant, options = {}) {
  const probe = git(worktree, ["merge-base", "--is-ancestor", ancestor, descendant], options);
  if (probe.ok) return "ancestor";
  if (probe.status === 1) return "not-ancestor";
  return "indeterminate";
}

export function runTests(worktree, command, { runner = spawnSync, skipReason = null, shellCommand = false, timeoutMs = DEFAULT_REPOSITORY_VERIFY_TIMEOUT_MS } = {}) {
  if (!command) {
    // Finding 1: defaulting a skip reason let omission manufacture review readiness.
    // Tests must be observed green or explicitly skipped with a caller-declared reason;
    // omission alone is neither.
    return { cmd: null, exit: null, observed: false, skipped_reason: skipReason };
  }
  const result = shellCommand
    ? runner(command, [], { cwd: worktree, shell: true, stdio: "inherit", env: process.env, timeout: timeoutMs })
    : runner(command[0], command.slice(1), { cwd: worktree, encoding: "utf8", shell: false });
  const exit = Number.isInteger(result?.status) ? result.status : null;
  return { cmd: shellCommand ? command : command.join(" "), exit, observed: exit !== null, skipped_reason: null };
}

export function deriveReviewReady(evidence) {
  if (evidence.status !== "completed") return false;
  // A tree with uncommitted changes cannot produce evidence about the commit it
  // claims, whatever the tests said.
  if (evidence.worktree_clean !== true) return false;
  if (!Array.isArray(evidence.files_changed) || evidence.files_changed.length === 0) return false;
  if (evidence.diff_observed !== true) return false;
  const tests = evidence.tests ?? {};
  if (tests.observed === true) return tests.exit === 0;
  // A skip is only acceptable when a reason was recorded. Absent tests with no
  // reason is the shape a fabricated pass would take.
  return typeof tests.skipped_reason === "string" && tests.skipped_reason.trim().length > 0;
}

export function reconcileClaim(claim, observation) {
  if (claim === null || claim === undefined) return { claimed: false, mismatches: [] };
  const mismatches = [];
  const compare = (field, claimed, observed) => {
    if (claimed === undefined || claimed === null) return;
    if (Array.isArray(claimed) && Array.isArray(observed)) {
      const claimedSet = [...claimed].sort().join("\n");
      const observedSet = [...observed].sort().join("\n");
      if (claimedSet !== observedSet) mismatches.push({ field, claimed, observed });
      return;
    }
    if (claimed !== observed) mismatches.push({ field, claimed, observed });
  };
  compare("commit", claim.commit, observation.commit);
  compare("files_changed", claim.files_changed, observation.files_changed);
  compare("status", claim.status, observation.status);
  // The important one: a claimed passing test against an observed failure or an
  // unobserved run.
  if (claim.tests?.exit !== undefined && claim.tests.exit !== null) {
    compare("tests.exit", claim.tests.exit, observation.tests?.exit ?? null);
  }
  return { claimed: true, mismatches };
}

