export function resolveWorktree(repo, worktree) {
  const absolute = resolve(repo, worktree);
  const rel = relative(resolve(repo), absolute);
  if (rel.startsWith("..") || rel.startsWith(sep) || !existsSync(absolute)) return null;
  return absolute;
}

